# 重現腳本

P0 和 P1 除了文字的重現步驟，還要有一份 Playwright 重現腳本。之後要確認修好了沒有，直接跑腳本就好，不需要再派 agent 重測。

腳本的斷言寫「**修好之後應該成立的事**」，所以：
- bug 還在：腳本失敗
- bug 修好：腳本通過

## 什麼時候寫

P0、P1 第二次從乾淨狀態重現成功之後。檔案放在 `.frontend-qa/<run>/repro/F<n>.spec.ts`，F 編號和 `findings.md` 相同。沒有 Playwright 也要寫，只是不能執行。

## 怎麼寫

1. 重現的時候用 chrome-cdp-ex 操作，結束後跑 `export-playwright <t>`，拿它的輸出當草稿。草稿通常**不能直接用**：
   - 可能少了登入步驟，也可能帶著登入時填的明文密碼。**刪掉草稿中的登入段落**，一律改用共用的 `repro/_login.ts`
   - `eval` 做的操作（例如連點）不會匯出
   - 沒有任何斷言
2. `_login.ts` 的網址用 `BASE_URL` 環境變數，密碼用 `QA_PASSWORD` 環境變數。**密碼不能寫進任何檔案**，登入失敗時也不能為了讓腳本跑起來就寫死
3. 用 `test.step` 把腳本分成「前置」和「斷言」兩段。觸發 bug 之前，前置裡一定要有**正向錨點**：確認現在真的在要測的畫面、而且畫面已經載入，例如 `await expect(page).toHaveURL(/projects\/new/)` 加上 `await expect(page.getByRole('heading', { name: '新增專案', exact: true })).toBeVisible()`（`exact: true`，否則「專案」也會比對到「新增專案」）。斷言是否定斷言（「不見了」「數量是 0」），而且用了 mock、延遲這類 route 觸發條件時，前置還要證明它**真的生效了**，例如 route 裡計數、前置最後 `await expect.poll(() => injected).toBeGreaterThan(0)`。沒有錨點的話，登入失效、被導回首頁，或 mock 沒攔到請求時，「某個東西不見了」這類斷言會直接通過，被誤判成已修
4. 補上觸發 bug 的那一步：

| 情境 | 寫法 |
|---|---|
| 連點 | `page.evaluate(() => { const b = document.querySelector('<sel>'); b.click(); b.click(); })`，同一個 task 內點兩次 |
| API 回錯誤 | `page.route((url) => url.pathname === '/api/<路徑>', (r) => { injected++; return r.fulfill({ status: 500, body: '{}' }); })`。用函式比對，網址加了 query 也攔得到 |
| 斷網 | `context.setOffline(true)` |
| 請求很慢 | `page.route(…, async (r) => { injected++; await new Promise((ok) => setTimeout(ok, 10000)); return r.continue(); })` |
| 換一個尺寸 | `test.use({ viewport: { width: <寬>, height: <高> } })` |

需要 `@playwright/test` 1.51 以上（`filter({ visible: true })`）。

5. 寫斷言，描述修好之後應該看到什麼。優先用「出現了什麼」的正向斷言；用「不見了」「數量是 0」這類否定斷言時，前面一定要有第 3 點的錨點。找文字時加上 `filter({ visible: true })`，因為表單常常預先埋了隱藏的錯誤元素：

```ts
// 失敗時要有看得見的錯誤訊息
await expect(page.getByText(/失敗|錯誤|無法/).filter({ visible: true }).first()).toBeVisible({ timeout: 5000 });

// 排序後第一列是日期最早的那一筆
await expect(page.locator('tbody tr').first()).toContainText('2026-01-03');

// 上傳後檔案出現在附件列表
await expect(page.getByRole('listitem').filter({ hasText: 'report.pdf' })).toBeVisible();

// 只發出一個寫入請求：先等第一個回應，再多等一段時間看有沒有第二個
const writes: string[] = [];
page.on('request', (r) => { if (r.method() !== 'GET' && r.url().includes('/api/projects')) writes.push(r.url()); });
// ……觸發……
await expect.poll(() => writes.length).toBeGreaterThan(0);
await page.waitForTimeout(1000);
expect(writes.length).toBe(1);
```

範例：

```ts
// repro/_login.ts
import type { Page } from '@playwright/test';
export const BASE = process.env.BASE_URL || 'http://localhost:3000';
export async function login(page: Page) {
  await page.goto(BASE + '/login');
  await page.locator('[name=email]').fill('qa@example.com');
  await page.locator('[name=password]').fill(process.env.QA_PASSWORD ?? '');
  await page.locator('form button').click();
  await page.waitForURL(/dashboard/);
}

// repro/F4.spec.ts
// F4 [P1] 依到期日排序後，第一頁的順序是錯的
import { test, expect } from '@playwright/test';
import { BASE, login } from './_login';
test('依到期日排序後，第一列是最早到期的專案', async ({ page }) => {
  await test.step('前置', async () => {
    await login(page);
    await page.goto(BASE + '/projects');
    await expect(page.getByRole('heading', { name: '專案', exact: true })).toBeVisible();
    await page.getByRole('columnheader', { name: '到期日' }).click();
  });
  await test.step('斷言', async () => {
    await expect(page.locator('tbody tr').first()).toContainText('2026-01-03');

        if (LOADING_WORDS.test(text) && !ERROR_WORDS.test(feedback))
          add('stuck-loading', list.url, `${scenario}：${feedbackMs}ms 後仍顯示「${(text.match(LOADING_WORDS) || [''])[0]}」，沒有錯誤訊息`, { scenario });
        else if (!ERROR_WORDS.test(feedback)) add('no-error-message', list.url, `${scenario}：${feedbackMs}ms 後畫面沒有錯誤訊息`, { scenario });
      });
    }
  }

  for (const form of config.forms || []) {
    if (!form.allowSubmit) {
      add('skipped', form.url, '表單沒有設定 allowSubmit: true，略過送出類檢查');
      continue;
    }
    // 連點：同一個 task 內 click() 兩次，計算寫入請求數
    await step('連點送出', form.url, async () => {
      await go(form.url);
      await fillForm(form.fill);
      reset();
      await clickTimes(form.submit, 2);
      await sleep(Math.max(2500, settleMs));
      if (events.dialogs.some((d) => d.type === 'confirm')) return add('skipped', form.url, '連點送出：送出前要求確認，腳本按了取消，無法判斷');
      const n = writes(form.api).length;
      if (n > 1) add('double-submit', form.url, `連點兩下送出，發出 ${n} 個寫入請求（${form.api}）`);
    });
    // 斷網送出、API 回 500（預設攔截所有寫入方法，不會真的寫到後端）
    await step('離線送出', form.url, () => feedbackAfterSubmit(form, '離線', () => setOffline(true), () => setOffline(false)));
    await step('API 500 送出', form.url, () =>
      feedbackAfterSubmit(form, 'API 500 ', () => setMocks([{ match: form.api, status: 500, method: form.method || 'WRITE' }]), () => setMocks([])));
    // 超長輸入：只填不送，檢查各尺寸會不會撐破版面
    if (form.longField) {
      for (const vp of viewports) {
        await step(`超長輸入 ${vp.name}`, form.url, async () => {
          await setViewport(vp);
          await go(form.url);
          await fillForm({ ...form.fill, [form.longField]: 'W'.repeat(300) });
          await sleep(200);
          const o = await evaluate(OVERFLOW);
          if (o) add('horizontal-overflow', form.url, `欄位 ${form.longField} 填入 300 字元無空格字串後 scrollWidth ${o}`, { viewport: vp.name, scenario: '超長輸入' });
        });
      }
    }
  }
} catch (err) {
  add('probe-error', '', String(err.message || err).split('\n')[0]);
} finally {
  if (sessionId && !dead) {
    await setOffline(false).catch(() => {});
    await send('Fetch.disable').catch(() => {});
  }
  if (targetId && !dead) await send('Target.closeTarget', { targetId }, { browser: true }).catch(() => {});
  if (browserContextId && !dead) await send('Target.disposeBrowserContext', { browserContextId }, { browser: true }).catch(() => {});
  writeOut();
  ws?.close();
}
process.exit(0);

